import React, { useState, useEffect } from 'react';
import './Dashboard.css';

const Dashboard = () => {
  const [overallStats, setOverallStats] = useState({
    totalContestants: 0,
    totalJudges: 0,
    totalCategories: 0,
    totalCriteria: 0,
    averageScore: 0,
    upcomingEvents: 0
  });

  const [recentContestants, setRecentContestants] = useState([]);
  const [recentJudges, setRecentJudges] = useState([]);
  const [topScores, setTopScores] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);

      // Fetch recent contestants
      const contestantsResponse = await fetch('http://localhost/Tabolator_Casestudy/backend/api/contestants');
      const contestantsData = await contestantsResponse.json();

      // Fetch recent judges  
      const judgesResponse = await fetch('http://localhost/Tabolator_Casestudy/backend/api/judges');
      const judgesData = await judgesResponse.json();

      // Fetch categories
      const categoriesResponse = await fetch('http://localhost/Tabolator_Casestudy/backend/api/categories');
      const categoriesData = await categoriesResponse.json();

      // Fetch criteria
      const criteriaResponse = await fetch('http://localhost/Tabolator_Casestudy/backend/api/criteria');
      const criteriaData = await criteriaResponse.json();

      // Calculate stats
      const activeContestants = contestantsData.data?.filter(c => c.status === 'Active') || [];
      const averageScore = calculateAverageScore(contestantsData.data || []);

      setOverallStats({
        totalContestants: contestantsData.data?.length || 0,
        totalJudges: judgesData.data?.length || 0,
        totalCategories: categoriesData.data?.length || 0,
        totalCriteria: criteriaData.data?.length || 0,
        averageScore: averageScore,
        upcomingEvents: 1 // This would come from events API
      });

      // Set recent data (last 5)
      setRecentContestants((contestantsData.data || []).slice(0, 5));
      setRecentJudges((judgesData.data || []).slice(0, 5));

      // Calculate top scores (mock data for now)
      setTopScores([
        { name: 'Sarah Martinez', score: 89.5, rank: 1 },
        { name: 'Jessica Chen', score: 87.2, rank: 2 },
        { name: 'Amanda Thompson', score: 85.8, rank: 3 }
      ]);

    } catch (error) {
      console.error('Dashboard data fetch error:', error);
    } finally {
      setLoading(false);
    }
  };

  const calculateAverageScore = (contestants) => {
    const scoredContestants = contestants.filter(c => c.final_score && c.final_score > 0);
    if (scoredContestants.length === 0) return 0;

    const total = scoredContestants.reduce((sum, c) => sum + parseFloat(c.final_score), 0);
    return (total / scoredContestants.length).toFixed(1);
  };

  if (loading) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner"></div>
        <p>Loading dashboard...</p>
      </div>
    );
  }

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h1>Admin Dashboard</h1>
        <div className="header-actions">
          <button className="refresh-btn" onClick={fetchDashboardData}>
            <i className="fi fi-rr-refresh"></i>
            Refresh
          </button>
        </div>
      </header>

      {/* Overall Statistics */}
      <section className="stats-section">
        <h2>Overall Statistics</h2>
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-icon">
              <i className="fi fi-rr-users"></i>
            </div>
            <div className="stat-info">
              <h3>{overallStats.totalContestants}</h3>
              <p>Total Contestants</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <i className="fi fi-rr-user"></i>
            </div>
            <div className="stat-info">
              <h3>{overallStats.totalJudges}</h3>
              <p>Total Judges</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <i className="fi fi-rr-folder"></i>
            </div>
            <div className="stat-info">
              <h3>{overallStats.totalCategories}</h3>
              <p>Categories</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <i className="fi fi-rr-chart-pie"></i>
            </div>
            <div className="stat-info">
              <h3>{overallStats.totalCriteria}</h3>
              <p>Criteria</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <i className="fi fi-rr-star"></i>
            </div>
            <div className="stat-info">
              <h3>{overallStats.averageScore}</h3>
              <p>Average Score</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <i className="fi fi-rr-calendar"></i>
            </div>
            <div className="stat-info">
              <h3>{overallStats.upcomingEvents}</h3>
              <p>Upcoming Events</p>
            </div>
          </div>
        </div>
      </section>

      <div className="dashboard-content">
        {/* Recent Contestants */}
        <section className="recent-section">
          <h2>Recent Contestants</h2>
          <div className="recent-list">
            {recentContestants.map((contestant, index) => (
              <div key={contestant.id} className="recent-item">
                <div className="item-avatar">
                  <i className="fi fi-rr-user"></i>
                </div>
                <div className="item-info">
                  <h4>{contestant.name}</h4>
                  <p>Status: <span className={`status ${contestant.status.toLowerCase()}`}>{contestant.status}</span></p>
                </div>
                <div className="item-meta">
                  <span className="rank">#{index + 1}</span>
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Recent Judges */}
        <section className="recent-section">
          <h2>Recent Judges</h2>
          <div className="recent-list">
            {recentJudges.map((judge, index) => (
              <div key={judge.id} className="recent-item">
                <div className="item-avatar">
                  <i className="fi fi-rr-user"></i>
                </div>
                <div className="item-info">
                  <h4>{judge.name}</h4>
                  <p>PIN: {judge.pin}</p>
                </div>
                <div className="item-meta">
                  <span className="active-badge">Active</span>
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Top Scores */}
        <section className="scores-section">
          <h2>Top Scores</h2>
          <div className="scores-list">
            {topScores.map((score, index) => (
              <div key={index} className="score-item">
                <div className="rank-badge">
                  #{score.rank}
                </div>
                <div className="score-info">
                  <h4>{score.name}</h4>
                  <p className="score-value">{score.score}</p>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
};

export default Dashboard;
